//! Crystalline Lineage
//! @prompt 00_nucleo/prompts/compiler/layout/block.md
//! @prompt-hash d6cbdbc6
//! @layer L1
//! @updated 2026-09-01
//!
//! Atomização (ADR-0109, P376): o layout de `Block` movido do monólito
//! `layout_content` para o arquivo da feature. Content-preserving — a lógica
//! é idêntica; só o endereço mudou. O `match` no núcleo delega numa linha.

use crate::entities::dir::Dir;
use crate::entities::elements::block::{BlockElem, BlockHeight};
use crate::entities::layout_types::{FrameItem, Length, Pt};
use crate::entities::rel::Rel;
use crate::entities::value::Value;

use super::{FontMetrics, ImageSizer, Layouter};

/// Resolve altura relativa contra a região exterior, sem multiplicar
/// `infinity * 0` no caso absoluto de páginas com altura automática.
pub(super) fn resolve_height_pt(
    height: Rel<Length>,
    font: f64,
    outer_height: f64,
) -> Option<f64> {
    let relative = if height.rel == 0.0 { 0.0 } else { outer_height * height.rel };
    let resolved = relative + height.abs.resolve_pt(font);
    (resolved.is_finite() && resolved >= 0.0).then_some(resolved)
}

/// Resolve largura relativa uma única vez contra a região exterior útil.
pub(super) fn resolve_width_pt(
    width: Rel<Length>,
    font: f64,
    outer_width: f64,
) -> Option<f64> {
    let relative = if width.rel == 0.0 { 0.0 } else { outer_width * width.rel };
    let resolved = relative + width.abs.resolve_pt(font);
    (resolved.is_finite() && resolved >= 0.0).then_some(resolved)
}

/// Layout do container `Block` (P156G/P242/P243/P247/P248/P250/P252/P273.6).
pub(super) fn layout<M: FontMetrics, S: ImageSizer>(
    layouter: &mut Layouter<M, S>,
    e: &BlockElem,
) {
    let (
        body,
        width,
        height,
        inset,
        breakable,
        outset,
        radius,
        clip,
        fill,
        stroke,
        spacing,
        above,
        below,
    ) = (
        &e.body,
        &e.width,
        &e.height,
        &e.inset,
        &e.breakable,
        &e.outset,
        &e.radius,
        &e.clip,
        &e.fill,
        &e.stroke,
        &e.spacing,
        &e.above,
        &e.below,
    );
    let font = layouter.style.size.val();
    let resolved_width = (*width)
        .and_then(|value| resolve_width_pt(value, font, layouter.available_width()));
    let resolved_height = match *height {
        Some(BlockHeight::Relative(value)) => {
            resolve_height_pt(value, font, layouter.available_height())
        }
        Some(BlockHeight::Fractional(_)) => layouter.fractional_block_height,
        None => None,
    };
    let inset_left = inset.left.resolve_pt(font);
    let inset_top = inset.top.resolve_pt(font);
    let inset_bottom = inset.bottom.resolve_pt(font);
    // inset.right é scope-out (mesma razão que Pad.right
    // em P156C — refino com refactor multi-region).

    // P247 — outset semantic real activação (cenário A audit:
    // outset zero-uso pré-P247). Margem externa visual que
    // expande bounds Shape mas NÃO afecta cursor interno do
    // body (paralelo a margin CSS).
    let outset_left = outset.left.resolve_pt(font);
    let outset_right = outset.right.resolve_pt(font);
    let outset_top = outset.top.resolve_pt(font);
    let outset_bottom = outset.bottom.resolve_pt(font);
    let has_shape = fill.is_some() || stroke.is_some();
    let has_outset = outset_left != 0.0
        || outset_right != 0.0
        || outset_top != 0.0
        || outset_bottom != 0.0;

    // 1. Termina linha em curso.
    if layouter.regions.current.cursor_x.0 > layouter.regions.current.line_start_x.0 {
        layouter.flush_line();
    }

    // P250 — spacing/above collapse (paridade vanilla CSS margin
    // collapse `max(prev.below, curr.above)` entre Blocks
    // consecutivos; `above` suprimido no primeiro Block dum
    // Sequence — sinalizado via `block_chain_active == false`).
    let has_custom_above = above.is_some() || spacing.is_some();
    let above_pt = above
        .or(*spacing)
        .map(|l| l.resolve_pt(font))
        .unwrap_or(font * super::vanilla_defaults::PAR_SPACING);
    if layouter.block_chain_active {
        let gap = if layouter.prev_margin_is_parbreak && has_custom_above {
            above_pt
        } else {
            layouter.prev_block_below_pending.max(above_pt)
        };
        let prev_descent = layouter.prev_block_equation_descent;
        layouter.regions.current.cursor_y =
            Pt(layouter.prev_line_baseline + prev_descent + gap);
        layouter.initial_baseline_pending = true;
    }
    layouter.prev_block_below_pending = 0.0;

    // P248 (M9d / M7+5; ADR-0079 Categoria A.4 cumulativa) —
    // Block.breakable semantic real activação: medição
    // antecipada via `measure_content_constrained` (puro;
    // §2.4 audit). Quando `breakable: false` E o bloco não
    // cabe no espaço restante mas cabe numa página inteira,
    // `new_page()` antecipa o break. Quando o bloco excede a
    // página inteira, emit normal (paridade vanilla
    // "overlong atómico"). Default `breakable: true` preserva
    // comportamento P156G literal.
    if !*breakable {
        let avail_w = resolved_width.unwrap_or_else(|| layouter.available_width());
        let (_, body_h) = layouter.measure_content_constrained(body, avail_w);
        let height_min = resolved_height.unwrap_or(0.0);
        let inner_h = body_h.max(height_min);
        let block_total_h =
            outset_top + inset_top + inner_h + inset_bottom + outset_bottom;
        let page_usable_h = layouter.available_height();
        let remaining_h =
            layouter.page_bottom_limit() - layouter.regions.current.cursor_y.0;
        if block_total_h <= page_usable_h && block_total_h > remaining_h {
            // Cabe em página nova mas não na actual → break antecipado.
            layouter.new_page();
        }
        // else: cabe na actual OU overlong (emit normal — paridade vanilla).
    }

    // P247 — snapshot items_before para inserir Shape ANTES
    // do body (Z-order: fill+stroke atrás do conteúdo).
    let items_before = layouter.regions.current.current_items.len();
    let page_before = layouter.pages.len();
    let deco_before = layouter.decoration_lines_collector.as_ref().map_or(0, Vec::len);

    // 2. Captura cursor.y para verificar height mínimo no fim.
    let start_y = layouter.regions.current.cursor_y.0;

    // P247 — outset.top avança cursor antes do inset.top
    // (margem externa precede margem interna).
    layouter.regions.current.cursor_y += Pt(outset_top);

    // 3. Aplica inset top.
    layouter.regions.current.cursor_y += Pt(inset_top);

    // 4. Aplica inset left (e width se especificado).
    let saved_line_start = layouter.regions.current.line_start_x;
    let saved_width = layouter.regions.current.width;
    let saved_height = layouter.regions.current.height;
    let is_rtl = layouter.chain.custom("text.dir").and_then(|value| match value {
        Value::Dir(dir) => Some(*dir),
        _ => None,
    }) == Some(Dir::RTL);
    let container_alignment = layouter.explicit_line_alignment.unwrap_or(if is_rtl {
        crate::entities::layout_types::HAlign::Right
    } else { crate::entities::layout_types::HAlign::Left });
    let block_origin_x = if let Some(w_pt) = resolved_width {
        let outer_width = w_pt + inset_left;
        match container_alignment {
            crate::entities::layout_types::HAlign::Right => Pt(saved_width - layouter.page_config.margin.right - outer_width),
            crate::entities::layout_types::HAlign::End => Pt(saved_width - layouter.page_config.margin.right - outer_width),
            crate::entities::layout_types::HAlign::Center => saved_line_start + Pt((layouter.available_width() - outer_width) / 2.0),
            crate::entities::layout_types::HAlign::Left => saved_line_start,
            crate::entities::layout_types::HAlign::Start => saved_line_start,
        }
    } else { saved_line_start };
    layouter.regions.current.line_start_x = block_origin_x + Pt(inset_left);
    layouter.regions.current.cursor_x = layouter.regions.current.line_start_x;

    // P243 (M9d / M7+3 fase (a); ADR-0081 IMPLEMENTADO parcial 4/5)
    // — promoção real `Block.width`: quando `Some(w)`,
    // clampa `regions.current.width` ao valor user-provided
    // durante body layout via save/restore. `width: None`
    // preserva largura herdada.
    if let Some(w_pt) = resolved_width {
        let line_start_pt = layouter.regions.current.line_start_x.0;
        // `Region.width` permanece em coordenadas de página e
        // `available_width()` desconta a margem direita; incluir essa margem
        // evita descontá-la duas vezes dentro do Block.
        layouter.regions.current.width =
            (line_start_pt + w_pt + layouter.page_config.margin.right).max(0.0);
    }
    // P1292 v12 — uma altura explícita também é a região efetiva dos
    // descendentes durante o body. Como o Block preserva coordenadas
    // absolutas no Layouter, o limite local é expresso a partir de `start_y`;
    // o outset superior fica fora da altura interna declarada. O limite
    // externo é restaurado logo após o body, como já ocorre com a largura.
    if let Some(h_pt) = resolved_height {
        layouter.regions.current.height = saved_height.min(start_y + outset_top + h_pt);
    }

    // P242 (M9d / M7+5) — clip=true emite FrameItem::Group com
    // clip_mask `RoundedRect{radii}` (radius non-zero) ou `Rect`
    // (radius zero; paridade DEBT-30 P79). Layouter restringe
    // body output em mask. Quando clip=false, comportamento
    // inline original preservado (semantic adiada graded mas
    // estrutura inline mantida).
    let radius_is_zero = radius.top_left == crate::entities::layout_types::Length::ZERO
        && radius.top_right == crate::entities::layout_types::Length::ZERO
        && radius.bottom_right == crate::entities::layout_types::Length::ZERO
        && radius.bottom_left == crate::entities::layout_types::Length::ZERO;

    if *clip {
        // P242 wrap em Group via snapshot-and-extract.
        // Layout body normalmente; snapshots de items count
        // antes/depois; extrai items emitidos pelo body e
        // re-emite como Group com clip_mask.
        let pos_block = crate::entities::layout_types::Point {
            x: layouter.regions.current.line_start_x,
            y: layouter.regions.current.cursor_y,
        };
        let items_before = layouter.regions.current.current_items.len();
        let y_before = layouter.regions.current.cursor_y;

        // P273.6 — save/restore parent_bbox (Decisão 3γ.2.γ:
        // popular apenas quando width+height literais).
        let saved_parent_bbox = layouter.parent_bbox;
        if let (Some(w_pt), Some(h_pt)) = (resolved_width, resolved_height) {
            layouter.parent_bbox = Some(crate::entities::layout_types::Rect {
                x: layouter.regions.current.cursor_x,
                y: layouter.regions.current.cursor_y,
                w: Pt(w_pt),
                h: Pt(h_pt),
            });
        }

        // Layout body (acumula items em current_items).
        layouter.layout_content(body);
        layouter.flush_line();

        // P273.6 — restore parent_bbox (LIFO).
        layouter.parent_bbox = saved_parent_bbox;

        // Extrair items adicionados pelo body.
        let body_items: Vec<FrameItem> =
            layouter.regions.current.current_items.drain(items_before..).collect();
        let inner_h = (layouter.regions.current.cursor_y - y_before).0;
        let inner_w = layouter.available_width();
        let clip_shape = if radius_is_zero {
            crate::entities::geometry::ShapeKind::Rect
        } else {
            super::resolve_shape_kind(
                &crate::entities::geometry::ShapeKind::RoundedRect { radii: *radius },
                layouter.style.size,
            )
        };
        // Re-emit como Group envolvendo os items extraídos.
        layouter.regions.current.current_items.push(FrameItem::Group {
            pos: pos_block,
            matrix: crate::entities::layout_types::TransformMatrix::identity(),
            clip_mask: Some(clip_shape),
            inner_width: inner_w,
            inner_height: inner_h,
            items: body_items,
        });
    } else {
        // P273.6 — save/restore parent_bbox (Decisão 3γ.2.γ).
        let saved_parent_bbox = layouter.parent_bbox;
        if let (Some(w_pt), Some(h_pt)) = (resolved_width, resolved_height) {
            layouter.parent_bbox = Some(crate::entities::layout_types::Rect {
                x: layouter.regions.current.cursor_x,
                y: layouter.regions.current.cursor_y,
                w: Pt(w_pt),
                h: Pt(h_pt),
            });
        }

        // 5. Layout do body (caminho original inline).
        layouter.layout_content(body);
        layouter.flush_line();

        // P273.6 — restore parent_bbox (LIFO).
        layouter.parent_bbox = saved_parent_bbox;
    }

    // Auto-sized textual frames are positioned as a unit. Do not change
    // paragraph direction to obtain the container's outer alignment.
    if resolved_width.is_none() && is_rtl && layouter.explicit_line_alignment.is_none()
        && !has_shape && !has_outset && !*clip
        && *inset == crate::entities::sides::Sides::uniform(Length::ZERO)
        && layouter.pages.len() == page_before
        && saved_width.is_finite() && super::placement::text_alignment_body(body)
        && items_before < layouter.regions.current.current_items.len()
    {
        let refs: Vec<_> = layouter.regions.current.current_items[items_before..].iter().collect();
        let right = layouter.metrics.line_content_right(&refs);
        let delta = saved_width - layouter.page_config.margin.right - right;
        for item in &mut layouter.regions.current.current_items[items_before..] {
            super::helpers::shift_frame_item_x(item, delta);
        }
        if let Some(segments) = layouter.decoration_lines_collector.as_mut() {
            for segment in &mut segments[deco_before..] {
                segment.start_x += Pt(delta); segment.end_x += Pt(delta);
            }
        }
    }

    // Descendentes do Block não podem fazer a região explícita vazar para o
    // flow exterior.
    layouter.regions.current.height = saved_height;

    // 6. Aplica inset bottom.
    layouter.regions.current.cursor_y += Pt(inset_bottom);

    // 7. Se height: Some(h), garantir que avançámos pelo menos h.
    //    h é altura INTERNA do bloco (sem outset); por isso
    //    compara com `cursor_y - start_y - outset_top` que é a
    //    altura consumida desde o topo interno.
    if let Some(h_pt) = resolved_height {
        let consumed_inner = layouter.regions.current.cursor_y.0 - start_y - outset_top;
        if consumed_inner < h_pt {
            layouter.regions.current.cursor_y += Pt(h_pt - consumed_inner);
        }
    }

    // P247 — outset.bottom avança cursor após inset.bottom +
    // height min (margem externa fecha o bloco).
    layouter.regions.current.cursor_y += Pt(outset_bottom);

    // P247 — emissão FrameItem::Shape (fill/stroke/outset).
    // Z-order: insere ANTES dos items do body (índice
    // items_before) para que fill+stroke renderizem por baixo
    // do conteúdo. Bounds outer incluem outset+inset+body.
    if has_shape || has_outset {
        let block_outer_w = match resolved_width {
            Some(w_pt) => w_pt + inset_left,
            None => saved_width - saved_line_start.0,
        };
        let mut outer_w = block_outer_w + outset_left + outset_right;
        let mut outer_h = layouter.regions.current.cursor_y.0 - start_y;
        let mut pos = crate::entities::layout_types::Point {
            x: block_origin_x - Pt(outset_left),
            y: Pt(start_y),
        };
        // P252 — stroke-overhang real activação Block.
        // Bounds Shape expandidos por thickness/2 em todos
        // os lados quando `stroke.overhang == true` (paridade
        // vanilla). Default Rust construtor `overhang: false`
        // preserva bounds literais (backward compat literal
        // pré-P252; sentinela p252).
        if let Some(ref s) = stroke {
            if s.overhang {
                // rationale: P1064 Classe 1B — semi-espessura de traço (thickness / 2.0)
                let ov = s.thickness / 2.0;
                pos.x = pos.x - Pt(ov);
                pos.y = pos.y - Pt(ov);
                outer_w += 2.0 * ov;
                outer_h += 2.0 * ov;
            }
        }
        let radius_is_zero_p247 = radius.top_left
            == crate::entities::layout_types::Length::ZERO
            && radius.top_right == crate::entities::layout_types::Length::ZERO
            && radius.bottom_right == crate::entities::layout_types::Length::ZERO
            && radius.bottom_left == crate::entities::layout_types::Length::ZERO;
        let shape_kind = if radius_is_zero_p247 {
            crate::entities::geometry::ShapeKind::Rect
        } else {
            super::resolve_shape_kind(
                &crate::entities::geometry::ShapeKind::RoundedRect { radii: *radius },
                layouter.style.size,
            )
        };
        layouter.regions.current.current_items.insert(
            items_before,
            FrameItem::Shape {
                pos,
                kind: shape_kind,
                width: outer_w,
                height: outer_h,
                fill: fill.clone().map(crate::entities::paint::Paint::Solid),
                stroke: stroke.clone(),
                // P273.6 — Block's own shape; gradient relative=parent
                // resolve para contentor outer (saved_parent_bbox foi
                // restaurado em parent_bbox antes desta emissão).
                fill_rule: Default::default(),
                parent_bbox_at_emit: layouter.parent_bbox,
            },
        );
    }

    // 8. Restaura line_start_x e width (P243).
    layouter.regions.current.line_start_x = saved_line_start;
    layouter.regions.current.cursor_x = saved_line_start;
    layouter.regions.current.width = saved_width;

    // P250/P1061 — below cursor.y advance + state update para
    // collapse com próximo Block/Parágrafo consecutivo.
    let is_geometric_container = height.is_some() || fill.is_some() || stroke.is_some();
    let has_explicit_margin = below.is_some() || spacing.is_some();
    let below_pt = if has_explicit_margin {
        below.or(*spacing).map(|l| l.resolve_pt(font)).unwrap_or(0.0)
    } else {
        font * super::vanilla_defaults::PAR_SPACING
    };

    if is_geometric_container {
        // P1292 v12 — o fim físico do frame é a fronteira lógica para a
        // unidade seguinte. O gap permanece pendente e colapsa pela mesma
        // regra de `above`/`below`; não é somado pelo Cursor nem pelo replay.
        let frame_end = layouter.regions.current.cursor_y.0;
        layouter.prev_line_baseline = frame_end;
        layouter.prev_block_below_pending = below_pt;
        layouter.block_chain_active = true;
    } else {
        let leading_pt = layouter
            .style
            .leading
            .map(|l| l.resolve_pt(font))
            .unwrap_or(font * super::vanilla_defaults::PAR_LEADING);
        let extra_below = below_pt - leading_pt;
        layouter.regions.current.cursor_y =
            Pt((layouter.regions.current.cursor_y.0 + extra_below).max(0.0));
        layouter.prev_block_below_pending = below_pt;
        layouter.block_chain_active = true;
    }
    layouter.prev_margin_is_parbreak = false;
}

#[cfg(test)]
mod p1373_tests {
    use super::*;

    #[test]
    fn p1373_height_100_percent_resolves_against_usable_region() {
        let height = Rel::<Length>::from_percent(100.0);
        let resolved = resolve_height_pt(height, 11.0, 220.0)
            .expect("100% de região finita deve resolver");
        assert!((resolved - 220.0).abs() < 1e-9, "resolved={resolved}");
    }

    #[test]
    fn p1373_mixed_height_preserves_absolute_offset() {
        let height = Rel::<Length>::from_percent(50.0) + Length::pt(10.0);
        let resolved = resolve_height_pt(height, 11.0, 220.0)
            .expect("altura relativa mista válida deve resolver");
        assert!((resolved - 120.0).abs() < 1e-9, "resolved={resolved}");
    }
}

#[cfg(test)]
mod p1374_tests {
    use super::*;

    #[test]
    fn p1374_width_60_percent_resolves_against_usable_region() {
        let width = Rel::<Length>::from_percent(60.0);
        let resolved = resolve_width_pt(width, 11.0, 180.0)
            .expect("60% de região finita deve resolver");
        assert!((resolved - 108.0).abs() < 1e-9, "resolved={resolved}");
    }
}

//! Crystalline Lineage
//! @prompt 00_nucleo/prompts/compiler/layout/measurement.md
//! @prompt-hash 6b680506
//! @layer L1
//! @updated 2026-10-05

use crate::entities::{
    content::Content,
    geometry::ShapeKind,
    image_sizer::{ImageSizer, NullImageSizer},
    layout_types::{FrameItem, Pt, TextStyle},
    style_chain::StyleChain,
};

use super::metrics::FontMetrics;
use super::{
    block, curve, resolve_pt, sub_frame, Layouter, COLUMNS_DEFAULT_GUTTER_RATIO,
};

impl<'a, M: FontMetrics, S: ImageSizer> Layouter<'a, M, S> {
    // ── Auxiliares de Grid (Passo 80) ─────────────────────────────────────

    /// P273.11 — Mede um Stack (children + dir + spacing) com `max_w`.
    /// Helper extraído da replicação inline P273.9 §2.2 (cleanup §9 P273.9).
    /// Decisão 1β Fase A: método em Layouter (reutiliza
    /// `measure_content_constrained` via `&self`).
    pub(super) fn measure_stack(
        &mut self,
        children: &[Content],
        dir: crate::entities::dir::Dir,
        spacing: Option<crate::entities::layout_types::Length>,
        max_w: f64,
    ) -> (f64, f64) {
        let n = children.len();
        if n == 0 {
            return (0.0, 0.0);
        }
        let space_pt = spacing.map_or(0.0, |l| l.resolve_pt(self.style.size.val()));
        if dir.is_vertical() {
            let mut max_child_w = 0.0_f64;
            let mut sum_h = 0.0_f64;
            for child in children.iter() {
                let (w, h) = self.measure_content_constrained(child, max_w);
                max_child_w = max_child_w.max(w);
                sum_h += h;
            }
            (max_child_w, sum_h + ((n - 1) as f64) * space_pt)
        } else {
            let mut sum_w = 0.0_f64;
            let mut max_child_h = 0.0_f64;
            for child in children.iter() {
                let (w, h) = self.measure_content_constrained(child, max_w);
                sum_w += w;
                max_child_h = max_child_h.max(h);
            }
            (sum_w + ((n - 1) as f64) * space_pt, max_child_h)
        }
    }

    /// Mede conteúdo com restrição de largura máxima.
    ///
    /// Usado pelo algoritmo de grid para determinar a largura das colunas Auto.
    /// Retorna `(width, height)` em pontos.
    pub(super) fn measure_content_constrained(
        &mut self,
        content: &Content,
        max_width: f64,
    ) -> (f64, f64) {
        match content {
            Content::Realized(e) => self.measure_content_constrained(&e.visual, max_width),
            Content::Located(e) => self.measure_content_constrained(&e.body, max_width),
            Content::ShowRecipe(e) => self.measure_content_constrained(&e.body, max_width),
            Content::Text(text) => {
                let mut max_line_w = 0.0_f64;
                let mut current_w = 0.0_f64;
                let mut line_count = 1usize;
                // **P624** — usa `text_width` (P593) para herdar shaping em
                // scripts contextuais, em vez de `advance` directo.
                let space_w =
                    self.metrics.text_width(" ", self.style.size, &self.style).0;

                for word in text.split_whitespace() {
                    let word_w =
                        self.metrics.text_width(word, self.style.size, &self.style).0;
                    let next_w = if current_w > 0.0 {
                        current_w + space_w + word_w
                    } else {
                        word_w
                    };
                    if next_w > max_width && current_w > 0.0 {
                        max_line_w = max_line_w.max(current_w);
                        line_count += 1;
                        current_w = word_w;
                    } else {
                        current_w = next_w;
                    }
                }
                max_line_w = max_line_w.max(current_w);
                let (_, line_height) =
                    self.metrics.vertical_metrics(self.style.size, &self.style);
                (max_line_w.min(max_width), line_height.0 * line_count as f64)
            }

            Content::Sequence(children) => {
                let mut total_h = 0.0_f64;
                let mut max_w = 0.0_f64;
                for child in children.iter() {
                    let (w, h) = self.measure_content_constrained(child, max_width);
                    total_h += h;
                    max_w = max_w.max(w);
                }
                (max_w, total_h)
            }

            Content::Shape(e) => {
                let (kind, width, height) = (&e.kind, &e.width, &e.height);
                match kind {
                    // P242 — RoundedRect partilha dimensões com Rect.
                    ShapeKind::Rect
                    | ShapeKind::RoundedRect { .. }
                    | ShapeKind::Ellipse
                    | ShapeKind::Path(_) => {
                        let w = resolve_pt(width.as_deref(), max_width).min(max_width);
                        let h = resolve_pt(height.as_deref(), 0.0);
                        (w, h)
                    }
                    ShapeKind::Line { dx, dy } => (dx.abs().min(max_width), dy.abs()),
                }
            }

            // Passo 513 — medição de `Content::Curve` via bbox do path.
            Content::Curve(e) => {
                let items =
                    curve::path_items_from_curve(&e.segments, self.style.size.val());
                let (min_x, min_y, max_x, max_y) =
                    crate::entities::geometry::path_bbox(&items);
                let w = (max_x - min_x).max(0.0).min(max_width);
                let h = (max_y - min_y).max(0.0);
                (w, h)
            }

            // Passo 156C / 156L: Pad / Hide para grid measurement.
            // P156L: cada side é Option<Length>; None ↔ zero.
            Content::Pad(e) => {
                let sides = &e.sides;
                let font = self.style.size.val();
                let left = sides.left.map_or(0.0, |l| l.resolve_pt(font));
                let right = sides.right.map_or(0.0, |l| l.resolve_pt(font));
                let top = sides.top.map_or(0.0, |l| l.resolve_pt(font));
                let bottom = sides.bottom.map_or(0.0, |l| l.resolve_pt(font));
                let constrained = (max_width - left - right).max(0.0);
                let (w, h) = self.measure_content_constrained(&e.body, constrained);
                (w + left + right, h + top + bottom)
            }
            Content::Hide(e) => self.measure_content_constrained(&e.body, max_width),

            // P408: smallcaps — stub transparente em medição (paridade layout).
            Content::SmallCaps { body } => {
                self.measure_content_constrained(body, max_width)
            }

            // Passo 156D: HSpace/VSpace dimensões para grid measurement.
            // **P842 (#38)** — `Fractional` mede 0 em contexto de medição
            // (o fr só expande contra o espaço restante de uma linha real;
            // numa medição isolada não há restante definido).
            Content::HSpace(e) => (
                match e.amount {
                    crate::entities::elements::h_space::Spacing::Absolute(l) => {
                        l.resolve_pt(self.style.size.val())
                    }
                    crate::entities::elements::h_space::Spacing::Fractional(_) => 0.0,
                },
                0.0,
            ),
            Content::VSpace(e) => (0.0, e.amount.resolve_pt(self.style.size.val())),

            // Passo 156E/220: Pagebreak/Colbreak — events sem dimensões em cell.
            Content::Pagebreak(_) => (0.0, 0.0),
            Content::Colbreak(_) => (0.0, 0.0),

            // Passo 156I: Stack dimensões para grid measurement.
            // TTB/BTT: max widths; sum heights + (n-1) * spacing.
            // LTR/RTL: sum widths + (n-1) * spacing; max heights.
            // P273.11 — delega ao helper Layouter::measure_stack (substitui
            // replicação inline ~25 LOC; bit-exact preserved).
            Content::Stack(e) => {
                self.measure_stack(&e.children, e.dir, e.spacing, max_width)
            }

            // Passo 156H: Boxed (Box inline) dimensões para grid
            // measurement. Análogo a Block (mesma lógica width/height/
            // inset; baseline ignorado em medição).
            Content::Boxed(e) => {
                let (body, width, height, inset) =
                    (&e.body, &e.width, &e.height, &e.inset);
                let font = self.style.size.val();
                let inset_l = inset.left.resolve_pt(font);
                let inset_r = inset.right.resolve_pt(font);
                let inset_t = inset.top.resolve_pt(font);
                let inset_b = inset.bottom.resolve_pt(font);
                let body_max = match width {
                    Some(w) => w.resolve_pt(font).min(max_width - inset_l - inset_r),
                    None => (max_width - inset_l - inset_r).max(0.0),
                };
                let (bw, bh) = self.measure_content_constrained(body, body_max);
                let total_w = bw + inset_l + inset_r;
                let body_h_with_inset = bh + inset_t + inset_b;
                let total_h = match height {
                    Some(h) => h.resolve_pt(font).max(body_h_with_inset),
                    None => body_h_with_inset,
                };
                (total_w, total_h)
            }

            // Passo 156J: Repeat dimensões para grid measurement.
            // Single-render do body (consistente with layout_content
            // arm). Algoritmo dinâmico de quantidade defere per
            // ADR-0054 graded.
            Content::Repeat(e) => self.measure_content_constrained(&e.body, max_width),

            // P219 (DEBT-56 sub-fase b 3/4): Columns dimensões para grid
            // measurement. Consumer real graded — calcula column_width
            // (paralelo a layout_content arm); medir body com width
            // reduzida; retorna full_width (columns ocupa width inteira)
            // + body_h (single-render graded).
            Content::Columns(e) => {
                let count_f = if e.count == 0 { 1.0 } else { e.count as f64 };
                let gutter_pt = match e.gutter {
                    Some(g) => g.resolve_pt(self.style.size.0),
                    None => max_width * COLUMNS_DEFAULT_GUTTER_RATIO,
                };
                let column_width = if count_f >= 1.0 {
                    (max_width - (count_f - 1.0) * gutter_pt) / count_f
                } else {
                    max_width
                };
                let (_body_w, body_h) =
                    self.measure_content_constrained(&e.body, column_width);
                (max_width, body_h)
            }

            // Passo 156G: Block dimensões para grid measurement.
            // Inset adiciona aos lados; height: Some(h) força mínimo;
            // width: Some(w) prefere essa largura mas constrained por max.
            Content::Block(e) => {
                let (body, width, height, inset) =
                    (&e.body, &e.width, &e.height, &e.inset);
                let font = self.style.size.val();
                let inset_l = inset.left.resolve_pt(font);
                let inset_r = inset.right.resolve_pt(font);
                let inset_t = inset.top.resolve_pt(font);
                let inset_b = inset.bottom.resolve_pt(font);
                let body_max = match width {
                    Some(w) => block::resolve_width_pt(*w, font, max_width)
                        .unwrap_or(max_width)
                        .min(max_width - inset_l - inset_r),
                    None => (max_width - inset_l - inset_r).max(0.0),
                };
                let (bw, bh) = self.measure_content_constrained(body, body_max);
                // P772f — largura explícita do bloco é a largura reportada
                // (o corpo mede-se dentro dela, mas não a substitui). Antes
                // usava sempre `bw`, colapsando a 0 quando o corpo era um
                // `Content::Align`/`Content::Place` sem braço próprio (ex:
                // `block(width: 3cm, align(top, place(..)))` numa coluna
                // auto de grid) — a coluna auto-dimensionava para 0pt.
                let total_w = match width {
                    Some(w) => block::resolve_width_pt(*w, font, max_width)
                        .unwrap_or(bw + inset_l + inset_r)
                        .min(max_width),
                    None => bw + inset_l + inset_r,
                };
                let body_h_with_inset = bh + inset_t + inset_b;
                let total_h = match height {
                    Some(crate::entities::elements::block::BlockHeight::Relative(h)) => {
                        block::resolve_height_pt(*h, font, self.available_height())
                            .unwrap_or(body_h_with_inset)
                            .max(body_h_with_inset)
                    }
                    Some(crate::entities::elements::block::BlockHeight::Fractional(
                        _,
                    )) => self
                        .fractional_block_height
                        .unwrap_or(body_h_with_inset)
                        .max(body_h_with_inset),
                    None => body_h_with_inset,
                };
                (total_w, total_h)
            }

            // P772f — `align` não tem tamanho intrínseco próprio: reporta o
            // tamanho do corpo (o wrapper só reposiciona dentro do espaço
            // disponível, não o redimensiona). Braço em falta colapsava a
            // 0 e fazia colunas auto de grid com células `align(...)`
            // colidirem na mesma posição x (ambas medidas a largura 0).
            Content::Align(e) => self.measure_content_constrained(&e.body, max_width),

            Content::Styled(styled) => {
                let body = &styled.body;
                let styles = &styled.styles;
                let prev_chain = self.chain.clone();
                let prev_style = self.style.clone();
                self.chain = self.chain.push_styles(styles);
                self.style = TextStyle::from(&self.chain);
                let res = self.measure_content_constrained(body, max_width);
                self.chain = prev_chain;
                self.style = prev_style;
                res
            }

            Content::Strong(e) => {
                use crate::entities::style::{Style, Styles};
                let prev_chain = self.chain.clone();
                let prev_style = self.style.clone();
                self.chain =
                    self.chain.push_styles(&Styles::from_iter([Style::strong()]));
                self.style = TextStyle::from(&self.chain);
                let res = self.measure_content_constrained(&e.body, max_width);
                self.chain = prev_chain;
                self.style = prev_style;
                res
            }

            Content::Emph(e) => {
                use crate::entities::style::{Style, Styles};
                let prev_chain = self.chain.clone();
                let prev_style = self.style.clone();
                self.chain = self.chain.push_styles(&Styles::from_iter([Style::emph()]));
                self.style = TextStyle::from(&self.chain);
                let res = self.measure_content_constrained(&e.body, max_width);
                self.chain = prev_chain;
                self.style = prev_style;
                res
            }

            _ => (0.0, 0.0), // neutro: N16[γ] — Content sem dimensão fixa explícita retorna (0.0, 0.0) (fallback de dimensão estática)
        }
    }
}

/// **P712/P858** — layout real e isolado de conteúdo para `measure()` (stdlib).
///
/// Constrói um `Layouter` isolado com `chain` = `chain` do chamador (o
/// tamanho medido depende do `#set text(size:)` activo, paridade com o
/// vanilla `measure()`, que usa `context.styles()`) e corre
/// `layout_sub_frame` (Passo 629 — o mesmo mecanismo já reutilizado por
/// `Content::Place`/`Content::Transform` e por `grid.rs` para medir
/// células) numa região efectivamente sem limites (`width:
/// f64::INFINITY`, `height: None`) — paridade com o vanilla
/// `Region::new(.., Abs::inf())` para a `measure()` sem `width`/`height`
/// explícitos. Devolve `(width, height)` em pontos, a partir dos itens
/// realmente emitidos pelo layout — não uma aproximação manual por tipo
/// de `Content` (ao contrário do antigo `measure_content` em
/// `layout/helpers.rs`, que continua a servir os seus próprios
/// consumers internos — `Content::Transform`/`Content::Place` —,
/// inalterado por este passo).
///
/// **P858** — recebe `metrics` do chamador (via `Engine::font_metrics`).
/// Durante a expansão de `#context`, a métrica real (`FallbackFontMetrics`,
/// L3) é injetada; noutros contextos, usa-se `FixedMetrics` como fallback
/// heurístico. A paridade com o vanilla é agora ao nível da língua
/// (medidas reais de fonte), não apenas proporcional.
pub fn measure_content_real(
    content: &Content,
    chain: &StyleChain,
    metrics: &dyn FontMetrics,
) -> (f64, f64) {
    let (width, height, _) = measure_content_real_with_baseline(content, chain, metrics);
    (width, height)
}

/// **P1491** — variante interna de `measure_content_real` que preserva a
/// baseline causal do frame medido. O helper público histórico mantém a
/// assinatura `(width, height)`; só o dispatch de `measure()` consome a
/// terceira coordenada.
pub(in crate::compiler) fn measure_content_real_with_baseline(
    content: &Content,
    chain: &StyleChain,
    metrics: &dyn FontMetrics,
) -> (f64, f64, f64) {
    use comemo::Track;

    let font_size = chain.size();
    let intr = crate::entities::introspector::TagIntrospector::empty();
    let intr_dyn: &dyn crate::entities::introspector::Introspector = &intr;
    let mut layouter =
        Layouter::new(metrics, NullImageSizer, font_size, intr_dyn.track());
    layouter.chain = chain.clone();
    layouter.style = TextStyle::from(chain);

    // P772x — `layouter` é uma instância isolada e efémera (só para medir);
    // não há collector ambiente possível aqui, `_deco` é sempre vazio.
    // **P908** — instância efémera, descartada inteira após a medição; não
    // há "pai" para propagar entradas órfãs de `pending_align_*` (`_x`/`_y`
    // abaixo) — mesmo descarte já correcto de antes.
    let (height, items, _deco, _orphaned_x, _orphaned_y) = layouter.layout_sub_frame(
        content,
        sub_frame::SubLayoutRegion {
            origin_x: 0.0,
            width: f64::INFINITY,
            height: None,
            align_rtl: false,
            unconstrained_height: true,
        },
    );

    let width = if items.is_empty() {
        0.0
    } else {
        let refs: Vec<&FrameItem> = items.iter().collect();
        metrics.line_content_right(&refs)
    };

    // **P860** — a altura deve ser a do frame de layout do texto, não o
    // avanço de linha de `layout_sub_frame`. Os edges padrão do vanilla
    // (`top-edge: cap-height`, `bottom-edge: baseline`) definem a altura de
    // um frame de texto; `text_edges` devolve `(top, bottom)` relativos à
    // baseline, pelo que a altura total é `top - bottom`.
    // Para conteúdo sem texto plano, mantém-se o fallback do avanço de linha.
    let text = content.plain_text();
    let (text_ascent, text_descent) = if text.is_empty() {
        (0.0, 0.0)
    } else {
        let (top, bottom) = metrics.text_edges(Pt(font_size), &layouter.style);
        (top.val(), -bottom.val())
    };

    let inline_ascent = layouter.line_inline_ascent.max(0.0);
    let inline_descent = layouter.line_inline_descent.max(0.0);
    let has_inline_frame = inline_ascent > 0.0 || inline_descent > 0.0;

    let (height, baseline) = if has_inline_frame {
        let ascent = text_ascent.max(inline_ascent);
        let descent = text_descent.max(inline_descent);
        (ascent + descent, ascent)
    } else if !text.is_empty() {
        (text_ascent + text_descent, text_ascent)
    } else if height > 0.0 {
        (height, height)
    } else {
        (0.0, 0.0)
    };

    (width, height, baseline)
}

